parameters.jsCode:
function normalizeUrl(url) {
  return (url ?? '')
    .toString()
    .trim()
    .replace(/\/+$/, '')
    .toLowerCase();
}

let resumir;
try {
  resumir = $('Resumir URLs pendientes').first().json;
} catch (e) {
  return [];
}
if (!resumir || !Array.isArray(resumir.pendingUrls) || resumir.pendingUrls.length === 0) {
  return [];
}

const pendingUrls = new Set(
  resumir.pendingUrls.map(u => normalizeUrl(u))
);

const urgentUrls = new Set(
  (resumir.urgentUrls || []).map(u => normalizeUrl(u))
);

const today = $now
  .setZone('America/Caracas')
  .toFormat('yyyy-MM-dd');

const eligible = items.filter(item => {
  const url = normalizeUrl(item.json.URL);

  if (!url || !pendingUrls.has(url)) return false;

  if (urgentUrls.has(url)) return true;

  const pf = (item.json['Próxima fecha'] ?? '').toString();
  const pfDate = pf.slice(0, 10);

  return pfDate <= today;
});

if (eligible.length === 0) {
  return [];
}

eligible.sort((a, b) => {
  const aUrl = normalizeUrl(a.json.URL);
  const bUrl = normalizeUrl(b.json.URL);

  const aUrgent = urgentUrls.has(aUrl) ? 0 : 1;
  const bUrgent = urgentUrls.has(bUrl) ? 0 : 1;

  if (aUrgent !== bUrgent) {
    return aUrgent - bUrgent;
  }

  const aDate = a.json['Última publicación'];
  const bDate = b.json['Última publicación'];

  if (!aDate && !bDate) return 0;
  if (!aDate) return -1;
  if (!bDate) return 1;

  return new Date(aDate) - new Date(bDate);
});

const selected = eligible[0];

return [
  {
    json: {
      ...selected.json,
      _isUrgent: urgentUrls.has(
        normalizeUrl(selected.json.URL)
      ),
    },
  },
];

const today = $now.setZone('America/Caracas').toFormat('yyyy-MM-dd');
const norm = (v) => (v ?? '').toString().trim().replace(/\/+$/, '').toLowerCase();
// Solo posts accionables: con URL de sitio y Temas informado.
// Un registro con fechas pero sin Temas se ignora aqui para no bloquear el loop.
const valid = items.filter(i => {
  const url = norm(i.json['URL del sitio']);
  const temas = (i.json['Temas'] ?? '').toString().trim();
  return url.length > 0 && temas.length > 0;
});
const urls = new Set(valid.map(i => norm(i.json['URL del sitio'])));
const urgentUrls = new Set(
  valid
    .filter(i => {
      const s = (i.json['Fecha creación'] ?? '').toString();
      return s.length >= 10 && s.slice(0, 10) === today;
    })
    .map(i => norm(i.json['URL del sitio']))
);
return [{ json: { pendingUrls: [...urls], urgentUrls: [...urgentUrls] } }];

const rawData = items[0]?.json;

let posts = [];
if (Array.isArray(rawData)) {
  posts = rawData;
} else if (items.length > 1) {
  posts = items.map(i => i.json).filter(Boolean);
}

if (posts.length === 0) {
  return [{ json: { postsIndex: 'No hay posts publicados aún en este sitio.' } }];
}

const lines = posts
  .filter(p => p && p.title && p.link)
  .map(p => {
    const title = typeof p.title === 'object'
      ? (p.title.rendered || '').replace(/<[^>]+>/g, '').trim()
      : String(p.title).trim();
    return `- ${title} → ${p.link}`;
  })
  .join('\n');

return [{ json: { postsIndex: lines || 'No hay posts publicados aún en este sitio.' } }];

